func PtoV(a, b Point) Point { return b.Sub(a) }
func Dot(a, b Point) float64 { return a.X*b.X + a.Y*b.Y }
func Cross(a, b Point) float64 { return a.X*b.Y - a.Y*b.X }
func Mod(a Point) float64 { return math.Sqrt(Dot(a, a)) }
func Mod2(a Point) float64 { return Dot(a, a) }
func Angle(a, b Point) float64 { // Corner2V
	return math.Abs(math.Acos(Dot(a, b) / Mod(a) / Mod(b)))
}
func Unit(a Point) Point { return a.Div(Mod(a)) }
func Rotate(v Point, alpha float64) Point {
	sa, ca := math.Sin(alpha), math.Cos(alpha)
	return Point{v.X*ca - v.Y*sa, v.X*sa + v.Y*ca}
}
func PRotate(p, o Point, alpha float64) Point {
	return o.Add(Rotate(PtoV(o, p), alpha))
}
func GetVV(v Point) Point { return Rotate(v, PI/2) }

func ShadowPOnLine(p, a, b Point) Point {
	ab := PtoV(a, b)
	ap := PtoV(a, p)
	// alph = Unit(ab) * Dot(ab, ap) / Mod(ab)
	// Dot(ab, ap) / Mod(ab) is projection length.
	// Unit(ab) is direction.
	// So vector from a to foot is Unit(ab) * (Dot(ab, ap) / Mod(ab))
	// Wait: Dot(ab, ap) = |ab| * |ap| * cos(theta). Projection of ap on ab is |ap|cos(theta) = Dot(ab, ap)/|ab|.
