	// Then point = a + vector.
	projectionLen := Dot(ab, ap) / Mod(ab)
	alph := Unit(ab).Mul(projectionLen)
	return a.Add(alph)
}

func LineCrossCircle(a, b, o Point, r float64) []Point {
	ret := make([]Point, 0, 2)
	t := ShadowPOnLine(o, a, b)
	ot := PtoV(o, t)
	dist := Mod(ot)
	if dist - r > eps {
		return ret
	}
	if math.Abs(dist - r) < eps {
		ret = append(ret, t)
		return ret
	}
	lr := math.Sqrt(r*r - Mod2(ot))
	// VecUnit(PtoV(t,a)) * lr
	dirA := Unit(PtoV(t, a))
	dirB := Unit(PtoV(t, b))
	ret = append(ret, t.Add(dirA.Mul(lr)))
	ret = append(ret, t.Add(dirB.Mul(lr)))
	return ret
}

func PointTangentCircle(p, o Point, r float64) []Point {
	ret := make([]Point, 0, 2)
	po := PtoV(o, p) // Vector from o to p? Wait C++: VecMod2(p-o). p-o is vector from o to p.
