	ret = append(ret, q1.Sub(q2))
	ret = append(ret, q1.Add(q2))
	return ret
}

func POnSeg(p, a, b Point) bool {
	if math.Abs(Cross(PtoV(a, b), PtoV(a, p))) > eps {
		return false
	}
	if math.Min(a.X, b.X) > p.X || p.X > math.Max(a.X, b.X) {
		return false
	}
	if math.Min(a.Y, b.Y) > p.Y || p.Y > math.Max(a.Y, b.Y) {
		return false
	}
	return true
}

func PDisLine(p, a, b Point) float64 {
	return Mod(ShadowPOnLine(p, a, b).Sub(p))
