		return vs*t > Mod(e.Sub(s))
	}

	ttp1 := PointTangentCircle(s, Point{0, 0}, r)
	// if PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e) swap
	if PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e) {
		ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
	}
	l1 := Mod(PtoV(s, ttp1[0]))

	ttp2 := PointTangentCircle(e, Point{0, 0}, r)
	if PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e) {
		ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
	}
	l2 := Mod(PtoV(e, ttp2[0]))

	alph := Angle(PtoV(Point{0, 0}, ttp1[0]), PtoV(Point{0, 0}, ttp2[0]))

	// return l1 + l2 + alph * r < vs * t
	return l1 + l2 + alph*r < vs*t
}

func main() {
	// Fast I/O
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	// Since we need to read 5 doubles per loop: p.x, p.y, vp, s.x, s.y, vs, r
	// Total 7 doubles.
	// C++: while(cin >> p >> vp >> s >> vs >> r)
	// p has x,y. vp double. s has x,y. vs double. r double.
